#include "CricketPhysics.hpp"
#include "MatchSimulation.hpp"
#include "BowlingAI.hpp"
#include <cassert>
#include <iostream>
int main(){cricket::CricketPhysics e;cricket::Delivery d;d.speedKph=135;d.length=.55f;e.startDelivery(d);for(int i=0;i<120&&e.ball().active;i++)e.update(1.f/120);e.reset();e.startDelivery(d);cricket::BatterInput in;in.timing=.5f;in.power=.9f;in.shot=cricket::ShotType::Drive;auto c=e.strike(in);assert(c.connected&&c.quality>.5f&&c.exitSpeed>30);cricket::MatchSimulation match({20,10,false});match.startInnings(50);match.setBatter(0,"Test Batter");match.recordDelivery(c,cricket::DeliveryResult::Runs,4);assert(match.innings().runs==4&&match.innings().batters[0].fours==1);assert(match.requiredRuns()==46);cricket::BowlingAI ai(26); cricket::BowlerProfile profile; profile.style=cricket::BowlerStyle::YorkerSpecialist; auto delivery=ai.chooseDelivery(profile,.8f,5); assert(delivery.length<.30f); std::cout<<"Cricket engine smoke test passed. Quality="<<c.quality<<" MatchRuns="<<match.innings().runs<<"\n";}